compile.workshop:
variables {
    global:
        0: arr
        1: n
        2: i
    player:
        0: parr
        1: pn
        2: pi
}

//Optimize for size enabled
rule ("values") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Modify Global Variable(arr, Append To Array, Char In String(Empty Array, False));
        Modify Global Variable(arr, Subtract, Char In String(Empty Array, False));
        Modify Global Variable(arr, Remove From Array By Value, Char In String(Empty Array, False));
        Modify Global Variable(n, Min, Char In String(Empty Array, False));
        Modify Global Variable(n, Max, Char In String(Empty Array, False));
        Modify Global Variable(n, Add, Char In String(Empty Array, False));
        Modify Global Variable(n, Multiply, Char In String(Empty Array, False));
        Modify Global Variable(n, Divide, Char In String(Empty Array, False));
        Modify Global Variable At Index(arr, False, Subtract, Char In String(Empty Array, False));
        Modify Global Variable At Index(arr, False, Append To Array, Char In String(Empty Array, False));
        Modify Player Variable(Event Player, parr, Append To Array, Char In String(Empty Array, False));
        Modify Player Variable(Event Player, pn, Subtract, Char In String(Empty Array, False));
        For Global Variable(i, 0, Char In String(Empty Array, False), True);
        End;
        For Global Variable(i, Char In String(Empty Array, False), 5, True);
        End;
        For Global Variable(i, 1, 5, Char In String(Empty Array, False));
        End;
        For Player Variable(Event Player, pi, 0, Char In String(Empty Array, False), True);
        End;
    }
}

